# validate_ageing_error ----
## Setup ----
data("data_big")
data_4_model <- FIMSFrame(data_big)
ages <- get_ages(data_4_model)
years <- get_start_year(data_4_model):get_end_year(data_4_model)
n_ages <- length(ages)

# Each age is read correctly with probability 0.7 and 1 year too old with
# probability 0.3, and the plus group is always read correctly. The matrix is
# not symmetric, so a transposed matrix gives different values.
reads_older <- diag(0.7, n_ages)
reads_older[cbind(1:(n_ages - 1), 2:n_ages)] <- 0.3
reads_older[n_ages, n_ages] <- 1

# Each true age is read correctly with probability 1 - value and as the
# youngest age with probability value, so value labels the matrix.
matrix_with <- function(value) {
  matrix <- diag(1 - value, n_ages)
  matrix[, 1] <- matrix[, 1] + value
  matrix
}

# Rows are true ages and columns are observed ages.
ageing_error_rows <- function(matrix = reads_older, fleet = NA_character_,
                              timing = NA_real_, observed_ages = ages) {
  tibble::tibble(
    type = "ageing_error",
    fleet = fleet,
    age = rep(observed_ages, times = nrow(matrix)),
    length = NA_real_,
    timing = timing,
    observed = as.vector(t(matrix)),
    unit = "proportion",
    uncertainty = as.character(rep(ages, each = ncol(matrix)))
  )
}

with_data <- function(...) dplyr::bind_rows(data_big, ...)

resolve <- function(...) {
  resolve_ageing_error(
    with_data(...),
    fleets = c("fleet1", "survey1"),
    ages = ages,
    years = years
  )
}

# Probability that a true age 2 fish is read as age 1 by a fleet in a year,
# which is the value given to matrix_with().
read_young_in <- function(resolved, fleet, year) {
  resolved |>
    dplyr::filter(
      .data[["fleet"]] == .env[["fleet"]],
      .data[["timing"]] == .env[["year"]],
      .data[["true_age"]] == ages[2],
      .data[["age"]] == ages[1]
    ) |>
    dplyr::pull(.data[["observed"]])
}

## IO correctness ----
test_that("validate_ageing_error() works with correct inputs", {
  #' @description Test that one matrix with timing = NA and fleet = NA is valid.
  expect_true(
    validate_ageing_error(with_data(ageing_error_rows()), ages, years)
  )

  #' @description Test that a default plus year-specific and fleet-specific matrices is valid.
  expect_true(validate_ageing_error(
    with_data(
      ageing_error_rows(),
      ageing_error_rows(timing = years[2]),
      ageing_error_rows(fleet = "fleet1"),
      ageing_error_rows(fleet = "fleet1", timing = years[3])
    ),
    ages,
    years
  ))

  #' @description Test that a matrix for every year without a default is valid.
  all_years <- purrr::map(years, \(year) ageing_error_rows(timing = year)) |>
    dplyr::bind_rows()
  expect_true(validate_ageing_error(with_data(all_years), ages, years))

  #' @description Test that probabilities summing to within 1e-3 of 1 are valid and give a warning that they are rescaled.
  rounded <- reads_older
  rounded[2, 2] <- rounded[2, 2] + 9e-4
  expect_warning(
    expect_true(
      validate_ageing_error(with_data(ageing_error_rows(rounded)), ages, years)
    ),
    "rescaled to sum to 1"
  )

  #' @description Test that a single probability rounded to just above 1 is valid and gives a warning that it is rescaled.
  rounded_up <- diag(n_ages)
  rounded_up[1, 1] <- 1 + 4e-4
  expect_warning(
    expect_true(
      validate_ageing_error(
        with_data(ageing_error_rows(rounded_up)),
        ages,
        years
      )
    ),
    "rescaled to sum to 1"
  )

  #' @description Test that data without ageing_error rows are valid.
  expect_true(validate_ageing_error(data_big, ages, years))
})

test_that("resolve_ageing_error() returns the matrix each fleet uses", {
  single <- resolve(ageing_error_rows())
  #' @description Test that a single default applies to each fleet with age-composition data.
  expect_equal(sort(unique(single[["fleet"]])), c("fleet1", "survey1"))
  #' @description Test that a single default matrix has timing = NA.
  expect_true(all(is.na(single[["timing"]])))
  #' @description Test that each fleet gets 1 matrix of n_ages^2 values.
  expect_equal(NROW(single), 2 * n_ages^2)
  fleet1 <- dplyr::filter(single, .data[["fleet"]] == "fleet1")
  #' @description Test that the matrix is returned with true age as rows and observed age fastest, not transposed.
  expect_equal(fleet1[["observed"]], as.vector(t(reads_older)))

  resolved <- resolve(
    ageing_error_rows(matrix_with(0.1)),
    ageing_error_rows(matrix_with(0.2), timing = years[2]),
    ageing_error_rows(matrix_with(0.3), fleet = "fleet1"),
    ageing_error_rows(matrix_with(0.4), fleet = "fleet1", timing = years[3])
  )
  #' @description Test that a fleet's own timing = NA matrix applies in a year without its own year rows.
  expect_equal(read_young_in(resolved, "fleet1", years[1]), 0.3)
  #' @description Test that a fleet's own timing = NA matrix takes precedence over fleet = NA year rows.
  expect_equal(read_young_in(resolved, "fleet1", years[2]), 0.3)
  #' @description Test that a fleet's own year-specific matrix takes precedence over its timing = NA matrix.
  expect_equal(read_young_in(resolved, "fleet1", years[3]), 0.4)
  #' @description Test that a fleet without rows of its own uses the fleet = NA default.
  expect_equal(read_young_in(resolved, "survey1", years[1]), 0.1)
  #' @description Test that a fleet without rows of its own uses fleet = NA year rows in that year.
  expect_equal(read_young_in(resolved, "survey1", years[2]), 0.2)
  #' @description Test that another fleet's year-specific matrix does not apply to a fleet.
  expect_equal(read_young_in(resolved, "survey1", years[3]), 0.1)
  #' @description Test that each fleet with year-specific matrices gets 1 matrix per model year.
  expect_equal(NROW(resolved), 2 * length(years) * n_ages^2)

  year_only <- resolve(
    ageing_error_rows(matrix_with(0.1)),
    ageing_error_rows(matrix_with(0.4), fleet = "fleet1", timing = years[3])
  )
  #' @description Test that a fleet with rows for only 1 year uses the fleet = NA default in its other years.
  expect_equal(read_young_in(year_only, "fleet1", years[1]), 0.1)
  #' @description Test that a fleet with rows for only 1 year uses them in that year.
  expect_equal(read_young_in(year_only, "fleet1", years[3]), 0.4)

  fleet_only <- resolve(ageing_error_rows(fleet = "survey1"))
  #' @description Test that without fleet = NA rows only fleets with their own rows get a matrix.
  expect_equal(unique(fleet_only[["fleet"]]), "survey1")
})

## Edge handling ----
test_that("resolve_ageing_error() does not depend on row order", {
  rows <- dplyr::bind_rows(
    ageing_error_rows(),
    ageing_error_rows(fleet = "fleet1", timing = years[2])
  )
  shuffled <- rows[c(nrow(rows):1), ]
  #' @description Test that shuffled rows, where true ages 10 to 12 sort before 2 as text, give the same matrices.
  expect_equal(resolve(shuffled), resolve(rows))
})

test_that("resolve_ageing_error() reads true ages stored as a factor", {
  # The levels of a factor sort as text, so its integer codes are not the
  # true ages.
  as_factor <- with_data(ageing_error_rows()) |>
    dplyr::mutate(uncertainty = factor(.data[["uncertainty"]]))
  #' @description Test that a factor true age is valid.
  expect_true(validate_ageing_error(as_factor, ages, years))
  #' @description Test that a factor true age gives the same matrices as a character true age.
  expect_equal(
    resolve_ageing_error(
      as_factor,
      fleets = c("fleet1", "survey1"),
      ages = ages,
      years = years
    ),
    resolve(ageing_error_rows())
  )
})

test_that("resolve_ageing_error() keeps fleet = NA apart from a fleet named NA", {
  resolved <- resolve_ageing_error(
    dplyr::bind_rows(
      ageing_error_rows(matrix_with(0.1)),
      ageing_error_rows(matrix_with(0.2), timing = years[2])
    ),
    fleets = "NA",
    ages = ages,
    years = years
  )
  #' @description Test that a fleet named "NA" uses the fleet = NA default.
  expect_equal(read_young_in(resolved, "NA", years[1]), 0.1)
  #' @description Test that a fleet named "NA" uses fleet = NA year rows in that year.
  expect_equal(read_young_in(resolved, "NA", years[2]), 0.2)
  #' @description Test that a fleet named "NA" gets 1 matrix per model year.
  expect_equal(NROW(resolved), length(years) * n_ages^2)
})

test_that("validate_ageing_error() keeps fleet = NA apart from a fleet named like its label", {
  odd_name <- "NA (all fleets)"
  renamed <- dplyr::mutate(
    data_big,
    fleet = ifelse(fleet == "fleet1", odd_name, fleet)
  )
  #' @description Test that rows for fleet = NA and a fleet named "NA (all fleets)" are not treated as duplicates.
  expect_no_error(validate_ageing_error(
    dplyr::bind_rows(
      renamed,
      ageing_error_rows(),
      ageing_error_rows(fleet = odd_name)
    ),
    ages = ages,
    years = years
  ))
})

test_that("resolve_ageing_error() makes rows that are close to 1 sum to 1", {
  rounded <- reads_older
  rounded[2, 2] <- rounded[2, 2] + 9e-4
  totals <- resolve(ageing_error_rows(rounded)) |>
    dplyr::summarize(
      total = sum(.data[["observed"]]),
      .by = dplyr::all_of(c("fleet", "true_age"))
    )
  #' @description Test that each true age sums to exactly 1 when its input sums to within 1e-3 of 1.
  expect_equal(totals[["total"]], rep(1, NROW(totals)), tolerance = 1e-14)
})

test_that("validate_ageing_error() folds observed ages beyond the model ages", {
  # Observed ages run 0 to 13 while model ages are 1 to 12.
  wide <- cbind(0.05, reads_older * 0.9, 0.05)
  rows <- ageing_error_rows(
    wide,
    observed_ages = c(min(ages) - 1, ages, max(ages) + 1)
  )

  #' @description Test that observed ages below the youngest and above the oldest model age give a warning.
  expect_warning(
    validate_ageing_error(with_data(rows), ages, years),
    "has observed ages outside the model ages"
  )

  youngest_true_age <- suppressWarnings(resolve(rows)) |>
    dplyr::filter(
      .data[["fleet"]] == "fleet1",
      .data[["true_age"]] == ages[1]
    ) |>
    dplyr::pull(.data[["observed"]])
  #' @description Test that probability on younger ages is added to the youngest model age.
  expect_equal(youngest_true_age[1], 0.05 + 0.9 * 0.7)
  #' @description Test that probability on older ages is added to the plus group.
  expect_equal(youngest_true_age[n_ages], 0.05)
  #' @description Test that the other observed ages are unchanged.
  middle_ages <- 2:(n_ages - 1)
  expect_equal(
    youngest_true_age[middle_ages],
    0.9 * reads_older[1, middle_ages]
  )
})

test_that("FIMSFrame() keeps the model years and ages when ageing_error is added", {
  data_with_ageing_error <- FIMSFrame(
    with_data(ageing_error_rows(), ageing_error_rows(timing = years[2]))
  )
  #' @description Test that ageing_error rows do not change the model years.
  expect_equal(get_n_years(data_with_ageing_error), length(years))
  #' @description Test that ageing_error rows do not change the model ages.
  expect_equal(get_ages(data_with_ageing_error), ages)
})

## Error handling ----
test_that("validate_ageing_error() returns correct error messages", {
  check <- function(...) validate_ageing_error(with_data(...), ages, years)

  #' @description Test that probabilities above 1 return an error.
  too_big <- ageing_error_rows()
  too_big[["observed"]][1] <- 1.5
  expect_error(check(too_big), "between 0 and 1")

  #' @description Test that -999 returns an error rather than being treated as missing data.
  missing_value <- ageing_error_rows()
  missing_value[["observed"]][1] <- -999
  expect_error(check(missing_value), "between 0 and 1")

  #' @description Test that a unit other than proportion returns an error.
  expect_error(
    check(dplyr::mutate(ageing_error_rows(), unit = "number")),
    "proportion"
  )

  #' @description Test that a true age that is not a whole number returns an error instead of being truncated.
  half_age <- ageing_error_rows()
  half_age[["uncertainty"]][1] <- "5.5"
  expect_error(check(half_age), "whole number")

  #' @description Test that a missing true age returns an error.
  no_true_age <- ageing_error_rows()
  no_true_age[["uncertainty"]][1] <- NA
  expect_error(check(no_true_age), "whole number")

  #' @description Test that a fleet name not in the data returns an error from `FIMSFrame()` rather than adding a fleet.
  expect_error(
    FIMSFrame(with_data(ageing_error_rows(fleet = "surveyX"))),
    "no catch, index, or composition"
  )

  #' @description Test that a timing outside the model years returns an error.
  expect_error(
    check(ageing_error_rows(), ageing_error_rows(timing = max(years) + 1)),
    "outside the model years"
  )

  #' @description Test that a duplicated row returns an error.
  rows <- ageing_error_rows()
  expect_error(check(rows, rows[1, ]), "one row for each true age")

  #' @description Test that a matrix missing a true age returns an error.
  expect_error(
    check(dplyr::filter(
      ageing_error_rows(),
      .data[["uncertainty"]] != max(ages)
    )),
    "must span the model ages"
  )

  #' @description Test that a matrix missing an observed age returns an error.
  expect_error(
    check(dplyr::filter(ageing_error_rows(), .data[["age"]] != ages[5])),
    "must span the model ages"
  )


  #' @description Test that probabilities that do not sum to 1 return an error.
  off_by_more <- reads_older
  off_by_more[2, 2] <- off_by_more[2, 2] + 2e-3
  expect_error(check(ageing_error_rows(off_by_more)), "must sum to 1")

  #' @description Test that a matrix whose columns, but not rows, sum to 1 returns an error.
  expect_error(check(ageing_error_rows(t(reads_older))), "must sum to 1")

  #' @description Test that an observed age no fish can be read as returns an error because the likelihood would be NaN.
  read_older <- matrix(0, n_ages, n_ages)
  read_older[cbind(1:(n_ages - 1), 2:n_ages)] <- 1
  read_older[n_ages, n_ages] <- 1
  expect_error(
    check(ageing_error_rows(read_older)),
    "at least 0.001"
  )

  #' @description Test that an observed age with a probability small enough to underflow returns an error.
  tiny_column <- diag(n_ages)
  tiny_column[5, 5] <- 0
  tiny_column[5, 6] <- 1
  tiny_column[6, 5] <- 5e-324
  tiny_column[6, 6] <- 1 - 5e-324
  expect_error(check(ageing_error_rows(tiny_column)), "at least 0.001")

  #' @description Test that missing years without a timing = NA default return an error rather than being filled.
  expect_error(
    check(ageing_error_rows(timing = years[2])),
    "missing years"
  )

  #' @description Test that the missing-years error names each fleet with its own missing years.
  expect_error(
    check(
      ageing_error_rows(fleet = "fleet1"),
      ageing_error_rows(fleet = "survey1", timing = years[2])
    ),
    "survey1 \\(1, 3"
  )

  #' @description Test that ageing_error rows without an uncertainty column return an error.
  no_uncertainty <- dplyr::bind_rows(
    dplyr::select(data_big, -"uncertainty"),
    dplyr::select(ageing_error_rows(), -"uncertainty")
  )
  expect_error(
    validate_ageing_error(no_uncertainty, ages, years),
    "whole number"
  )
})

test_that("validate_ageing_error() warns when ageing_error rows are not used", {
  # Rows for true ages 0 and 13, outside the model ages 1 to 12.
  outside_true_ages <- dplyr::bind_rows(
    ageing_error_rows() |>
      dplyr::filter(.data[["uncertainty"]] == min(ages)) |>
      dplyr::mutate(uncertainty = as.character(min(ages) - 1)),
    ageing_error_rows() |>
      dplyr::filter(.data[["uncertainty"]] == max(ages)) |>
      dplyr::mutate(uncertainty = as.character(max(ages) + 1))
  )
  #' @description Test that rows for true ages outside the model ages give a warning.
  expect_warning(
    validate_ageing_error(
      with_data(ageing_error_rows(), outside_true_ages),
      ages,
      years
    ),
    "true ages outside the model ages"
  )
  resolved <- resolve(ageing_error_rows(), outside_true_ages)
  #' @description Test that rows for true ages outside the model ages are not used.
  expect_equal(sort(unique(resolved[["true_age"]])), ages)
  #' @description Test that dropping those rows leaves the matrix for the model ages unchanged.
  expect_equal(
    resolved[resolved[["fleet"]] == "fleet1", ][["observed"]],
    as.vector(t(reads_older))
  )

  no_survey_age_comp <- dplyr::filter(
    data_big,
    !(.data[["type"]] == "age_comp" & .data[["fleet"]] == "survey1")
  )
  #' @description Test that rows for a fleet without age-composition data give a warning.
  expect_warning(
    validate_ageing_error(
      dplyr::bind_rows(
        no_survey_age_comp,
        ageing_error_rows(),
        ageing_error_rows(fleet = "survey1")
      ),
      ages,
      years
    ),
    "not used for fleets without"
  )

  no_age_comp <- dplyr::filter(data_big, .data[["type"]] != "age_comp")
  #' @description Test that fleet = NA rows give a warning when no fleet has age-composition data.
  expect_warning(
    validate_ageing_error(
      dplyr::bind_rows(no_age_comp, ageing_error_rows()),
      ages,
      years
    ),
    "no fleet has"
  )
})

test_that("validate_ageing_error() is silent for fleets without ageing error", {
  # The test helpers set messages to quiet, so turn them on for these checks.
  withr::local_options(rlib_message_verbosity = "default")
  #' @description Test that data without ageing_error rows give no message or warning.
  expect_silent(validate_ageing_error(data_big, ages, years))
  #' @description Test that a fleet without rows of its own uses the identity matrix with no message or warning.
  expect_silent(
    validate_ageing_error(
      with_data(ageing_error_rows(fleet = "survey1")),
      ages,
      years
    )
  )
})
